  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--current-bg); 
  opacity: var(--current-tint-opacity); 
  z-index: 2; pointer-events: none;
  transition: background-color 0.3s ease, opacity 0.3s ease;
