  position: relative; 
  z-index: 3;
  display: flex; 
  align-items: center; 
  justify-content: flex-start;
  padding-left: 24px;
  height: 100%; 
  gap: 12px; 
}

.icon-box {
  display: flex; align-items: center; justify-content: center;
}

.icon-box svg {
  width: 44px; 
  height: auto;
}

.icon-box svg rect,
.icon-box svg path {
  transition: fill 0.3s ease, stroke 0.3s ease;
  will-change: fill, stroke;
}

.text-box {
  display: flex; flex-direction: column; gap: 2px; 
}

.title {
  font-size: 14px; font-weight: 600; 
  color: var(--current-title);
  letter-spacing: 0.2px; line-height: 1.15;
  transition: color 0.3s ease;
}

.subtitle {
  font-size: 12px; font-weight: 500; 
  color: var(--current-sub);
  line-height: 1.15;
  transition: color 0.3s ease;
}

.mz-slider-widget {
  width: 100%; height: 100%; position: relative; touch-action: none; 
}

/* 核心内壳层：恢复原样，不再对它使用 clip-path */
.slider-inner {
  width: 100%; height: 100%; 
  border-radius: 30px; 
  position: absolute; top: 0; left: 0;
  overflow: hidden; box-sizing: border-box;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1);
  /* 🌟 补回这行开启硬件加速，删掉 clip-path */
  transform: translateZ(0); 
}

/* 🌟 底层：纯粹的物理高斯模糊层 */
.glass-blur {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  backdrop-filter: blur(35px) saturate(180%);
  -webkit-backdrop-filter: blur(35px) saturate(180%);
  z-index: 1; pointer-events: none;

  /* 🌟 防溢出补丁直接打在这里！ */
  border-radius: 30px;
  overflow: hidden;
  -webkit-clip-path: inset(0 round 30px);
  clip-path: inset(0 round 30px);
}

/* 🌟 颜色染色层 */
.glass-tint {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--bg-color); 
  opacity: 0.45; /* 强制半透 */
  z-index: 2; pointer-events: none;

  /* 🌟 防溢出补丁也打在这里！ */
  border-radius: 30px;
  overflow: hidden;
  -webkit-clip-path: inset(0 round 30px);
  clip-path: inset(0 round 30px);
}

/* 白色亮度实体填充层 */
.slider-fill {
  position: absolute; bottom: 0; left: 0; right: 0; height: 0%; 
  background-color: var(--fill-color); 
  opacity: 0.95; 
  z-index: 3;
}

/* 太阳图标独立容器 */
.slider-icon-wrapper {
  position: absolute; bottom: 24px; left: 50%; transform: translateX(-50%);
  z-index: 4; pointer-events: none; 
  width: 40px; height: 40px;
  display: flex; justify-content: center; align-items: center;
  color: var(--icon-color);
}

/* 太阳 SVG 图标形变动画设定 */
.slider-icon-wrapper svg {
  width: 32px; height: 32px;
  transform-origin: center center;
}

/* 利用 currentColor 自动继承父级的颜色变量 */
.sun-part {
  fill: currentColor;
}

