            100% { height: 16px; } /* 顶部向上生发高度 */
        }

        /* --- 8. 页脚与极简控制器 --- */
        .st-editorial-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 4px;
