/* ==========================================
   气泡小尾巴 + 气泡两侧装饰图标
   ⚠️ 小尾巴：::before 画三角
   ⚠️ 装饰图标：::after 放图片（垂直居中）
   ========================================== */

/* ---------- 我方气泡 ---------- */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  background: #ffffff !important;
  border: 1px solid #666666 !important;      /* ⚠️ 气泡边框：灰黑色 */
  border-radius: 12px !important;
  z-index: 0 !important;
}

/* 我方尾巴：保留 border-right + border-bottom，rotate(45deg) 尖角朝正下 */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  bottom: -4px !important;                    /* ⚠️ 数字越大越往下 */
  right: 12px !important;                     /* ⚠️ 数字越大越往左（往里） */
  width: 6px !important;                      /* ⚠️ 尾巴大小 */
  height: 6px !important;                     /* ⚠️ 尾巴大小 */
  background: #ffffff !important;
  border-right: 1px solid #666666 !important; /* ⚠️ 与气泡边框同色 */
  border-bottom: 1px solid #666666 !important;/* ⚠️ 与气泡边框同色 */
  transform: rotate(45deg) !important;        /* 尖角朝正下 */
  z-index: 1 !important;
  pointer-events: none !important;
}

/* 我方气泡左侧装饰图标（垂直居中，无论几行都在中间）
   ⚠️ 改图：修改 url 链接
   ⚠️ 大小：width / height 控制尺寸
   ⚠️ 位置：left 控制左右 | top 50% + translateY(-50%) 垂直居中 */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  left: -12px !important;                     /* ⚠️ 负数越小越往左，越大越往里 */
  top: 50% !important;                        /* ⚠️ 垂直居中 */
  transform: translateY(-50%) !important;     /* ⚠️ 配合 top 实现垂直居中 */
  width: 22px !important;                     /* ⚠️ 图标大小 */
  height: 22px !important;                    /* ⚠️ 图标大小 */
  background: url("https://imgbed.heliar.top/i/WuIBCv7KGo8hLmrM_retouch_2026091317333126.webp") no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 2 !important;
}

/* 我方气泡里的文字内容：顶到最上层 */
.bubble-me-custom > * {
  position: relative !important;
  z-index: 3 !important;
}

/* ---------- 对方气泡 ---------- */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  background: #ffffff !important;
  border: 1px solid #666666 !important;      /* ⚠️ 气泡边框：灰黑色 */
  border-radius: 12px !important;
  z-index: 0 !important;
}

/* 对方尾巴：保留 border-left + border-bottom，rotate(-45deg) 尖角朝正下 */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  bottom: -4px !important;                    /* ⚠️ 数字越大越往下 */
  left: 12px !important;                      /* ⚠️ 数字越大越往右（往里） */
  width: 6px !important;                      /* ⚠️ 尾巴大小 */
  height: 6px !important;                     /* ⚠️ 尾巴大小 */
  background: #ffffff !important;
  border-left: 1px solid #666666 !important;  /* ⚠️ 与气泡边框同色 */
  border-bottom: 1px solid #666666 !important;/* ⚠️ 与气泡边框同色 */
  transform: rotate(-45deg) !important;       /* 尖角朝正下 */
  z-index: 1 !important;
  pointer-events: none !important;
}

/* 对方气泡右侧装饰图标（垂直居中，无论几行都在中间）
