/* 隐藏所有卡片类特殊消息的装饰贴图 */
.bubble-me-custom.no-padding::before,
.bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::before,
.bubble-them-custom.no-padding::after {
    display: none !important;
}

/* ==========================================
   头像框
   ⚠️ top：数字越小越往上
   ⚠️ left/right：负数越小越往左/右
   ⚠️ width/height：控制大小
   ⚠️ 改图：修改 url 链接
   ========================================== */

.msg-avatar-them-container,
.msg-avatar-me-container {
  overflow: visible !important;
  position: relative !important;
}

.msg-avatar-them-container::before {
  content: "" !important;
  position: absolute !important;
  top: -3% !important;
  left: 1px !important;
  transform: translateY(-50%) !important;
  width: 36px !important;
  height: 36px !important;
  background: url("https://i.imgs.ovh/2026/07/19/ed9dcb1eab9af836ceb40826773c2205.png") no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 10 !important;
  border-radius: 0 !important;
}

.msg-avatar-me-container::before {
  content: "" !important;
  position: absolute !important;
  top: -5% !important;
  right: -2px !important;
  transform: translateY(-50%) !important;
  width: 25px !important;
  height: 25px !important;
  background: url("https://i.imgs.ovh/2026/07/19/17d2c681e51b915e5c4d2bf6c6ecd179.png") no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 10 !important;
  border-radius: 0 !important;
}

/* 输入框提示词 */
.input-area-custom{
  background:transparent !important;
  position:relative !important;
}
.input-box-custom{
  background:transparent !important;
  border:none !important;
  padding-left:42px;
  color:var(--pink-main) !important;
  -webkit-mask-image:none !important;
  background-image:none !important;
  position:relative !important;      /* ⚠️ 建立层叠上下文 */
  z-index:1 !important;              /* ⚠️ 输入框层级较低 */
}
/*原生占位全透明*/
.input-box-custom::placeholder {
  color: transparent !important;
  opacity:0;
}
/*空白显示提示，输入内容父容器匹配，隐藏伪元素*/
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  display:none !important;
}
/*自定义提示样式 水平居中 + 往上挪 + 层级在输入框上面 */
.input-area-custom::before {
  content:"是ฅ՞熊猫团子՞ฅ啊";
  color: var(--pink-main) !important;
  position:absolute;
  left:50%;                          /* ⚠️ 水平居中 */
  top:calc(50% - 29px);               /* ⚠️ 垂直往上挪29px，数字越大越往上 */
  transform: translateX(-50%);       /* ⚠️ 只做水平居中，垂直不处理 */
  pointer-events:none;
  font-size:13px;
  white-space:nowrap;                /* ⚠️ 防止文字换行，保证居中准确 */
  z-index:99 !important;             /* ⚠️ 提示词层级高，显示在输入框上面 */
  position:absolute !important;      /* ⚠️ 确保绝对定位生效 */
}
/*原生占位透明保留属性，保证:placeholder-shown正常识别*/
.input-box-custom::placeholder {
  color: transparent !important;
}

/* ============================================
   顶栏底边框 - 黑色横线
   ⚠️ 调色：#1a1a1a 黑色
   ⚠️ 粗细：1px 可改成 1.5px / 2px
   ============================================ */
.chat-header-custom {
  border-bottom: 1px solid #1a1a1a !important;
  box-shadow: none !important;
}

/* ============================================
   底栏底色 - 白色
   ⚠️ 调色：#ffffff 纯白
   ============================================ */
.input-area-custom {
  background: #ffffff !important;
}

/* =================================== */
/* 顶栏高度变量 */
/* =================================== */
:root{
  --new-top-bar-height:85px;
  --new-top-content-y:40px;
}

/* =================================== */
/* 底栏样式变量 */
/* =================================== */
:root{
  --input-top-space:3px;
  --bottom-lift-space:20px;

  --box-border-width:1.5px;
  --box-border-radius:5px;
  --box-right-space:66px;
  --box-left-space:-10px;
  --box-top-offset:7px;
  --box-bottom-offset:7px;

  --input-box-pull-left:-27px;
  --input-box-pull-right:-37px;
  --input-text-padding-left:10px;

  --right-btn-size:28px;
  --right-mic-size:18px;

  --typing-btn-bottom:1.5px;
}
/* 当底栏包含引用预览栏时，底部距离抬高 4px */
.input-area-custom:has(.input-reply-preview-bar) {
  padding-bottom: calc(var(--bottom-lift-space) + 4px) !important;
}
/* =================================== */
/* 全局调位置 */
/* =================================== */
:root{
  --wechat-title-x:35px;
  --wechat-title-y:5px;
  --btn-back-translate-x:0px;
  --btn-back-translate-y:3px;
  --btn-info-translate-x:0px;
  --btn-info-translate-y:5px;

  --unread-num-top:13px;
  --unread-num-left:18px;
  --unread-num-font-size:10px;
  --unread-num-font-weight:700;
  --unread-num-padding:0 7px;
  --unread-num-height:18px;

  --voice-btn-x:-13px;
  --voice-btn-y:-5px;
  --voice-btn-size:28px;

  --btn-mic-x:28px;
  --btn-mic-y:0px;
  --btn-sticker-x:26px;
  --btn-sticker-y:0px;
  --btn-ai-send-x:22px;
  --btn-ai-send-y:0px;

  --fake-sticker-x:26px;
  --fake-sticker-y:0px;
  --real-send-x:22px;
  --real-send-y:0px;

  --gen-plus-x:24px;
  --gen-icon-y:49.5%;
  --gen-sticker-x:-16px;
  --gen-sticker-y:50.5%;
  --gen-mic-x:-77px;
  --gen-mic-y:25.8px;
}

