/* =================================== */
/* 🍓 通话 by小Q怡 */
/* =================================== */
:root{
  --call-avatar-image:url('https://nos.netease.com/ysf/b162f75b7995445115f2da8ee4af6b9c.png');
  --call-card-bg-me:#95ec69;
  --call-card-bg-them:#ffffff;
  --call-text-main:#1a1a1a;
  --call-text-me-cancel:"已取消";
  --call-text-them-reject:"对方已取消";
  --call-text-connected:"通话时长 ";
}
.msg-videocall-card,
.msg-videocall-card.missed,
.msg-videocall-card.connected,
.msg-videocall-card.cancelled,
.msg-videocall-card.rejected{
  width:fit-content!important;
  min-width:0!important;
  max-width:240px!important;
  padding:6px 10px!important;
  border-radius:4px!important;
  box-shadow:none!important;
  border:none!important;
  display:flex!important;
  align-items:center!important;
  gap:8px!important;
  position:relative!important;
  cursor:default!important;
  /* 默认（对方）颜色 */
  background: var(--call-card-bg-them) !important;
  background-color: var(--call-card-bg-them) !important;
}
:is(.msg-me, .bubble-me-custom) :is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected),
:is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected).msg-me {
  background: var(--call-card-bg-me) !important;
  background-color: var(--call-card-bg-me) !important;
}
:is(.msg-them, .bubble-them-custom) :is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected),
:is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected).msg-them {
  background: var(--call-card-bg-them) !important;
  background-color: var(--call-card-bg-them) !important;
}
.msg-me .msg-videocall-card::after,
.bubble-me-custom .msg-videocall-card::after,
.msg-videocall-card.msg-me::after{
  content:""!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  left:auto!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background:var(--call-card-bg-me)!important;
  background-color:var(--call-card-bg-me)!important;
  border-radius:2px!important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
}
.msg-them .msg-videocall-card::before,
.bubble-them-custom .msg-videocall-card::before,
.msg-videocall-card.msg-them::before{
  content:""!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  right:auto!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background:var(--call-card-bg-them)!important;
  background-color:var(--call-card-bg-them)!important;
  border-radius:2px!important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
}

.msg-videocall-card > div:first-child{
  width:24px!important;
  height:24px!important;
  min-width:24px!important;
  min-height:24px!important;
  border-radius:0!important;
  background:var(--call-avatar-image) center / contain no-repeat!important;
  background-color:transparent!important;
  background-image:var(--call-avatar-image)!important;
  box-shadow:none!important;
  border:none!important;
  flex-shrink:0!important;
  font-size:0!important;
  color:transparent!important;
  overflow:visible!important;
  display:block!important;
}
.msg-videocall-card > div:first-child svg,
.msg-videocall-card > div:first-child svg *{
  display:none!important;
  visibility:hidden!important;
  opacity:0!important;
  width:0!important;
  height:0!important;
  fill:transparent!important;
  stroke:transparent!important;
  filter:none!important;
}
.msg-videocall-card > div:nth-child(2){
  display:flex!important;
  flex-direction:row!important;
  align-items:center!important;
  justify-content:flex-start!important;
  max-width:none!important;
  gap:4px!important;
}
.msg-videocall-card > div:nth-child(2) > div:first-child{
  font-weight:500!important;
  color:var(--call-text-main)!important;
  -webkit-text-fill-color:var(--call-text-main)!important;
  letter-spacing:0!important;
  white-space:nowrap!important;
  overflow:hidden!important;
  margin:0!important;
  font-size:0!important;
}
.msg-videocall-card > div:nth-child(2) > div:first-child::before{
  font-size:14px!important;
  font-weight:500!important;
  color:var(--call-text-main)!important;
  -webkit-text-fill-color:var(--call-text-main)!important;
  content:"通话已结束"!important;
}
.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before{content:var(--call-text-me-cancel)!important;}
.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before{content:var(--call-text-them-reject)!important;}
.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before{content:var(--call-text-connected)!important;}
.msg-videocall-card > div:nth-child(2) > div:nth-child(2),
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) *{
  display:none!important;
  visibility:hidden!important;
  opacity:0!important;
  width:0!important;
  height:0!important;
  font-size:0!important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2){
  display:inline-flex!important;
  visibility:visible!important;
  opacity:1!important;
  width:auto!important;
  height:auto!important;
  font-size:14px!important;
  font-weight:500!important;
  color:var(--call-text-main)!important;
  -webkit-text-fill-color:var(--call-text-main)!important;
  margin:0!important;
  padding:0!important;
  background:transparent!important;
  gap:0!important;
  letter-spacing:0!important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) *{
  display:inline!important;
  visibility:visible!important;
  opacity:1!important;
  width:auto!important;
  height:auto!important;
  font-size:14px!important;
  color:var(--call-text-main)!important;
  -webkit-text-fill-color:var(--call-text-main)!important;
}
.msg-videocall-card > div:nth-child(3),
.msg-videocall-card > div:nth-child(3) *{
  display:none!important;
  visibility:hidden!important;
  opacity:0!important;
  width:0!important;
  height:0!important;
}
/* =========================================================
