}
.input-box-custom::placeholder { 
  color: transparent !important; 
  opacity: 0 !important; 
  font-size: 0px !important; 
}

/* Slide to unlock 静态文案 */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::after {
  content: "slide to unlock";
  position: absolute; 
  left: 8px; 
  top: 50%; 
  transform: translateY(-50%);
  font-size: 15px; 
  color: var(--text-sub, rgba(60, 60, 67, 0.45)) !important; 
  letter-spacing: 0.3px;
  pointer-events: none; 
