.input-area-custom .more-options-item-row svg {
  color: var(--more-options-color) !important;
  stroke: var(--more-options-color) !important;
}

/* =========================================================
   7. 【纯正 8 瓣 iOS 原生菊花 Spinner 终止键】
   ========================================================= */
@keyframes ios8BladeIndicator {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.stop-btn-custom {
  width: 42px !important; height: 42px !important; 
