  -webkit-mask-size: contain; -webkit-mask-position: center; -webkit-mask-repeat: no-repeat;

  backdrop-filter: blur(28px) saturate(160%);
  -webkit-backdrop-filter: blur(28px) saturate(160%);
  z-index: 2;
}

#dateGlass {
  top: 18%; 
