}

#timeGlass {
  top: 22%; 
  bottom: 0%; 
}

/* =========================================
   🌟 双路毛玻璃共用类（提亮到 1.06）
========================================= */
.glass-layer {
  position: absolute; left: -5%; right: -5%; 
  background-size: contain; background-position: center; background-repeat: no-repeat;
  -webkit-mask-size: contain; -webkit-mask-position: center; -webkit-mask-repeat: no-repeat;

  /* 🌟 核心提亮：在滤镜最后加上 brightness(1.06) */
  backdrop-filter: blur(28px) saturate(160%) brightness(1.2);
  -webkit-backdrop-filter: blur(28px) saturate(160%) brightness(1.2);

  /* 备用提亮方案：如果底层壁纸太暗，也可以再加一层整体提亮滤镜 */
  filter: brightness(1.2); 

  z-index: 2;
}

