.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* ================= 1. 根容器 (透明背景) ================= */
.xt-root {
    width: 360px !important; height: 600px !important;
    background: transparent !important; 
    position: relative !important; margin: 20px auto !important;
    overflow: hidden !important; pointer-events: auto !important;
}

/* 背景波点装饰 (低饱和淡青灰) */
.xt-root::before, .xt-root::after {
    content: '' !important; position: absolute !important;
    background-image: radial-gradient(#d8ecec 30%, transparent 30%) !important;
    background-size: 12px 12px !important;
    z-index: 1 !important;
}
.xt-root::before {
    top: 20px !important; right: 40px !important; width: 60px !important; height: 60px !important;
    border-radius: 50% !important; transform: rotate(15deg) !important;
}
.xt-root::after {
    bottom: 30px !important; left: 30px !important; width: 50px !important; height: 50px !important;
    border-radius: 50% !important;
}

/* ================= 2. 主纸张 ================= */
.xt-text:nth-of-type(1) {
    position: absolute !important; top: 60px !important; left: 25px !important;
    width: 310px !important; height: 460px !important;
    background-color: #ffffff !important;
    /* 笔记本横线 (极淡的青色) */
    background-image: repeating-linear-gradient(transparent, transparent 23px, #e8f4f4 23px, #e8f4f4 24px) !important;
    background-position: 0 30px !important;
    border-radius: 8px !important;
    transform: rotate(-4deg) !important;
    box-shadow: -6px 12px 20px rgba(130, 150, 150, 0.12) !important;
    z-index: 2 !important;
}
/* 左侧打孔效果 */
.xt-text:nth-of-type(1)::before {
    content: '' !important; position: absolute !important; top: 0 !important; left: -8px !important;
    width: 16px !important; height: 100% !important;
    background-image: radial-gradient(circle at 8px 12px, transparent 5px, #ffffff 5.5px) !important;
    background-size: 16px 24px !important;
    background-position: 0 10px !important;
    filter: drop-shadow(-2px 0px 1px rgba(130, 150, 150, 0.08)) !important;
}

/* ================= 3. 左上角胶带 ================= */
.xt-text:nth-of-type(2) {
    position: absolute !important; top: 65px !important; left: 35px !important;
    width: 80px !important; height: 25px !important;
    background-color: rgba(230, 242, 242, 0.95) !important; 
    background-image: radial-gradient(circle, #b0c4c4 1.5px, transparent 2px) !important;
    background-size: 10px 10px !important;
    transform: rotate(-15deg) !important;
    box-shadow: 1px 2px 4px rgba(130, 150, 150, 0.15) !important;
    z-index: 5 !important;
}

/* ================= 4. 右上角标题网格纸条 ================= */
.xt-text:nth-of-type(3) {
    position: absolute !important; top: 65px !important; right: 20px !important;
    width: 190px !important; height: 50px !important;
    background-color: #ffffff !important;
    background-image: 
        repeating-linear-gradient(0deg, transparent, transparent 9px, #e0f0f0 9px, #e0f0f0 10px),
        repeating-linear-gradient(90deg, transparent, transparent 9px, #e0f0f0 9px, #e0f0f0 10px) !important;
    transform: rotate(3deg) !important;
    box-shadow: 2px 4px 8px rgba(130, 150, 150, 0.1) !important;
    z-index: 4 !important;
}
.xt-text:nth-of-type(3)::before {
    content: '' !important; position: absolute !important; top: -6px !important; left: 0 !important;
    width: 100% !important; height: 12px !important;
    background-image: radial-gradient(circle at 8px 6px, transparent 3px, #ffffff 3.5px) !important;
    background-size: 16px 12px !important;
}

/* ================= 5. 标题文字 ================= */
.xt-text:nth-of-type(4) {
    position: absolute !important; top: 70px !important; right: 95px !important;
    font-family: 'Impact', 'Arial Black', sans-serif !important;
    font-size: 22px !important; color: #8eb5b5 !important; 
    transform: rotate(3deg) !important;
    letter-spacing: 1px !important;
    z-index: 5 !important;
}
.xt-text:nth-of-type(5) {
    position: absolute !important; top: 100px !important; right: 35px !important;
    font-size: 10px !important; color: #a3c2c2 !important;
    transform: rotate(3deg) !important;
    z-index: 5 !important;
}

/* ================= 6. 主纸张文字内容 ================= */
/* 左侧文字 */
.xt-text:nth-of-type(6) {
    position: absolute !important; top: 118px !important; left: 40px !important;
    width: 140px !important;
    font-size: 12px !important; color: #6b8e8e !important; 
    line-height: 24px !important; 
    transform: rotate(-4deg) !important;
    z-index: 3 !important;
}
/* 右侧文字 */
.xt-text:nth-of-type(7) {
    position: absolute !important; left: 195px !important; 
    top: 136px !important; 
    width: 110px !important;
    font-size: 12px !important; color: #6b8e8e !important; 
    line-height: 24px !important;
    transform: rotate(-5deg) !important;
    z-index: 3 !important;
}
/* 底部文字 */
.xt-text:nth-of-type(8) {
    position: absolute !important; top: 405px !important; left: 200px !important;
    font-size: 10px !important; color: #a3c2c2 !important;
    transform: rotate(-4deg) !important;
    z-index: 3 !important;
}

/* ================= 7. 💗右下角小人 ================= */
.xt-text:nth-of-type(9) {
    position: absolute !important; bottom: 20px !important; right: 10px !important;
    width: 160px !important; height: 200px !important;
    background-image: url('https://i.postimg.cc/L8DXt654/IMG-5055.png') !important; 
    background-size: contain !important;
    background-position: bottom right !important;
    background-repeat: no-repeat !important;
    z-index: 6 !important;
    filter: drop-shadow(2px 4px 6px rgba(130, 150, 150, 0.2)) !important;
}

/* ================= 8. 装饰元素 ================= */
/* 水滴 1 */
.xt-text:nth-of-type(10) {
    position: absolute !important; bottom: 120px !important; right: 260px !important;
    width: 10px !important; height: 10px !important;
    background-color: #a8d0d0 !important; 
    border-radius: 0 50% 50% 50% !important;
    transform: rotate(45deg) !important;
    z-index: 5 !important;
}
/* 水滴 2 */
.xt-text:nth-of-type(11) {
    position: absolute !important; bottom: 90px !important; right: 285px !important;
    width: 8px !important; height: 8px !important;
    background-color: #a8d0d0 !important;
    border-radius: 0 50% 50% 50% !important;
    transform: rotate(45deg) !important;
    z-index: 5 !important;
}
/* 小气泡 O(IVI)O */
.xt-text:nth-of-type(12) {
    position: absolute !important; bottom: 150px !important; right: 5px !important;
    padding: 2px 6px !important;
    border: 1px solid #d8ecec !important;
    border-radius: 4px !important;
    background: #ffffff !important;
    font-size: 10px !important; color: #8eb5b5 !important;
    z-index: 7 !important;
    box-shadow: 1px 2px 4px rgba(130, 150, 150, 0.1) !important;
}
.xt-text:nth-of-type(12)::before {
    content: '' !important; position: absolute !important; top: 50% !important; left: -4px !important;
    transform: translateY(-50%) rotate(45deg) !important;
    width: 6px !important; height: 6px !important;
    background: #ffffff !important;
    border-left: 1px solid #d8ecec !important;
    border-bottom: 1px solid #d8ecec !important;
}

